import unittest

from solution import SnippetTemplate


class SnippetTemplateTests(unittest.TestCase):
    def test_defaults_and_fresh_results(self):
        template = SnippetTemplate()
        first = template.render("alpha\nbeta\n")
        second = template.render("alpha\nbeta\n")
        self.assertEqual(first, {
            "dialect": "text",
            "content": "alpha\nbeta",
            "source_span": (0, 2),
        })
        self.assertEqual(second, first)
        self.assertIsNot(first, second)

    def test_tags_trim_overrides_and_input_stability(self):
        defaults = {"dialect": "python", "open_tag": "BEGIN", "trim": 2}
        template = SnippetTemplate(defaults)
        defaults["dialect"] = "changed"
        defaults["open_tag"] = None
        overrides = {"close_tag": "END", "trim": 3}
        result = template.render(
            "ignored\nBEGIN\n    one\n two\nEND\nafter", overrides
        )
        self.assertEqual(result, {
            "dialect": "python",
            "content": " one\ntwo",
            "source_span": (2, 4),
        })
        self.assertEqual(overrides, {"close_tag": "END", "trim": 3})

    def test_empty_selection(self):
        result = SnippetTemplate({"open_tag": "[", "close_tag": "]"}).render(
            "[\n]\nunused"
        )
        self.assertEqual(result["content"], "")
        self.assertEqual(result["source_span"], (1, 1))

    def test_missing_tags(self):
        with self.assertRaises(ValueError):
            SnippetTemplate({"open_tag": "missing"}).render("a\nb")
        with self.assertRaises(ValueError):
            SnippetTemplate({"close_tag": "missing"}).render("a\nb")
        with self.assertRaises(ValueError):
            SnippetTemplate({"open_tag": "OPEN", "close_tag": "CLOSE"}).render(
                "CLOSE\nOPEN\ndata"
            )

    def test_unknown_options(self):
        with self.assertRaises(ValueError):
            SnippetTemplate({"unknown": 1})
        with self.assertRaises(ValueError):
            SnippetTemplate().render("x", {"unknown": 1})

    def test_type_and_trim_validation(self):
        for source in (None, 3, ["x"]):
            with self.assertRaises(TypeError):
                SnippetTemplate().render(source)
        for options in (
            {"dialect": None},
            {"open_tag": 1},
            {"close_tag": []},
        ):
            with self.assertRaises(TypeError):
                SnippetTemplate(options).render("x")
        for trim in (True, 1.5, -1):
            expected = TypeError if trim is True or trim == 1.5 else ValueError
            with self.assertRaises(expected):
                SnippetTemplate({"trim": trim}).render("x")


if __name__ == "__main__":
    unittest.main()

